import { after } from "next/server";
import { revalidatePath } from "next/cache";
import { getAllStoreSlugs } from "@/lib/data";
import { storePathsForSlug } from "@/lib/storePaths";
import { warmPaths } from "@/lib/warmPaths";

/**
 * Full-site cache bust, run after every production deploy. `revalidatePath`
 * only invalidates the OLD deployment's already-cached HTML for pages that
 * used `export const revalidate` — a fresh deploy ships new code but does
 * NOT by itself throw out ISR pages generated by the previous deployment, so
 * without this, a code/UI change can sit uncalled-for on already-warm pages
 * (store pages especially, at revalidate=86400) for up to 24h.
 *
 * `revalidatePath("/", "layout")` busts every route sharing the root
 * layout — i.e. the entire app — in one call and runs synchronously so it's
 * guaranteed done before this returns. Only the PPC store paths are then
 * re-warmed (not every page on the site): those are the ones where a cold
 * on-demand render costs a paid click a multi-second wait: see
 * [[ppc-store-page-caching]]. Everything else (blog, categories, home) has a
 * much shorter revalidate window already and just regenerates on its next
 * natural visit. Warming itself runs via `after()` — must be called from
 * within an active request (a route handler), matching the pattern already
 * used by /api/revalidate for admin-triggered busts — so the caller's
 * response isn't held open for however long warming every store takes.
 */
export async function revalidateAllPPCPaths(origin: string) {
  revalidatePath("/", "layout");

  const slugs = await getAllStoreSlugs();
  const paths = slugs.flatMap(storePathsForSlug);

  after(async () => {
    await warmPaths(paths, origin);
  });

  return { stores: slugs.length, paths: paths.length };
}
